parameters.jsCode:
const rows = $input.all().map(i => i.json);
const total = rows.length;
const norm = s => String(s || '').toLowerCase();
const cnt = v => rows.filter(r => norm(r.screen) === v).length;
const fit = rows.filter(r => norm(r.screen) === 'fit');
const closer = rows.filter(r => ['fit','review'].includes(norm(r.screen)));
const sheet = 'https://docs.google.com/spreadsheets/d/1gUhvTA2UxxctxwXwsrxz6R82nnpXKhuQWF_4kqZz3oY/edit';
const fitList = fit.map(r => '@' + r.username).join(', ');
let text = `*🔎 Prospect screen — ${total} new*\n`;
text += `✅ fit: ${cnt('fit')}   🟡 review: ${cnt('review')}   🕓 later: ${cnt('later')}   ⛔ no: ${cnt('no')}\n`;
text += `*${closer.length}* need a closer look → <${sheet}|Open the Screened sheet>`;
if (fit.length) text += `\n\n*Fit:* ${fitList}`;
return [{ json: { digest: text, total, closer: closer.length } }];
